// Step 1: Create parameter expression
ParameterExpression pe = Expression.Parameter(typeof(Student), "s");

// Step 2: Create property expression
MemberExpression me = Expression.Property(pe, "Age");

// Step 3: Create constant expression
ConstantExpression constant = Expression.Constant(18, typeof(int));

// Step 4: Create binary expression
BinaryExpression body = Expression.GreaterThanOrEqual(me, constant);

// Step 5: Create lambda expression
var isAdultExprTree = Expression.Lambda<Func<Student, bool>>(body, new[] { pe });

Console.WriteLine($"Expression Tree: {isAdultExprTree}");
Console.WriteLine($"Body: {isAdultExprTree.Body}");
Console.WriteLine($"Parameters: {isAdultExprTree.Parameters[0]}");

Expression<Func<Student, bool>> isTeenAgerExpr = s => s.Age > 12 && s.Age < 20;

Console.WriteLine($"Expression: {isTeenAgerExpr}");
Console.WriteLine($"Expression Type: {isTeenAgerExpr.NodeType}");

var parameters = isTeenAgerExpr.Parameters;
foreach (var param in parameters)
{
    Console.WriteLine($"Parameter Name: {param.Name}");
    Console.WriteLine($"Parameter Type: {param.Type.Name}");
}

var bodyExpr = isTeenAgerExpr.Body as BinaryExpression;
Console.WriteLine($"Left side: {bodyExpr.Left}");
Console.WriteLine($"Binary Expression Type: {bodyExpr.NodeType}");
Console.WriteLine($"Right side: {bodyExpr.Right}");
Console.WriteLine($"Return Type: {isTeenAgerExpr.ReturnType}");
